	// has its own guard; "merge" there is an ordinary identifier, not the
	// changes-merge keyword.
	if len(segs) >= 4 && segs[1] == "documents" && segs[3] == "crdt" {
		return false
	}
	for i, seg := range segs {
		if seg != "merge" {
			continue
		}
