package events

// subKey identifies the set of subscriptions belonging to one device's view
// of one document: change commits wake every device set under the document,
// a permission revoke closes only the one (document, device) set.
type subKey struct {
	document string
	device   string
}

// subscription is one in-memory, push-only observer of the change log.
//
// It belongs to a (document, device) pair — the device is the one owning the
// session that opened the connection. It receives one coalesceable signal per
// change-producing commit (PostChanges, ReplayChanges, MergeChange and
// RestoreSnapshot all signal through the same hook long polling uses). The
// permission service closes the separate one-shot revoked channel when it
// revokes the keyed pair; closing is sticky, so a later grant never reopens
// it.
//
// A subscription leaves no durable trace: nothing is written, a disconnect
// simply unregisters, and a stop broadcasts one final wakeup. Pushing never
// allocates a cursor or inserts a change row.
type subscription struct {
	// wakes receives one value on every change commit for the keyed document.
	// It is buffered (and signals coalesce) so a commit is never dropped or
	// blocked while the consumer is reading the log.
	wakes chan struct{}
	// revoked is closed once, the first time permission for the keyed pair is
	// revoked while this subscription is live. Closing is sticky.
	revoked       chan struct{}
	revokedClosed bool
}

// AddSubscription registers an in-memory subscription for documentID as seen
// by deviceID. It returns:
//
//   - wakes: signaled (coalesceably) after every change commit on documentID;
//   - revoked: closed once if/when permission for (documentID, deviceID) is
//     revoked while the subscription is live;
//   - unregister: idempotent removal; a client disconnect, a permission close
//     and a service stop may all race to call it.
//
// If the service is already stopping the wake channel is signaled immediately
// and unregister is a no-op, so a late subscriber parks on nothing.
func (s *Service) AddSubscription(documentID, deviceID string) (wakes <-chan struct{}, revoked <-chan struct{}, unregister func()) {
	ch := make(chan struct{}, 1)
	sub := &subscription{wakes: ch, revoked: make(chan struct{})}
	key := subKey{document: documentID, device: deviceID}

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		close(ch)
		return ch, sub.revoked, func() {}
	}
	s.subWG.Add(1)
	s.nextSub++
	id := s.nextSub
	set := s.subs[key]
	if set == nil {
		set = make(map[uint64]*subscription)
		s.subs[key] = set
	}
	set[id] = sub
	remove := func() {
		s.mu.Lock()
		if set, ok := s.subs[key]; ok {
			if _, ok := set[id]; ok {
				delete(set, id)
				if len(set) == 0 {
					delete(s.subs, key)
				}
				s.mu.Unlock()
				s.subWG.Done()
				return
			}
		}
		s.mu.Unlock()
	}
	return ch, sub.revoked, remove
}

// signalSubscribers wakes every subscription open on documentID. It is called
// only after a change-bearing transaction has committed, so when a woken
// subscription re-reads the log the new rows are visible.
func (s *Service) signalSubscribers(documentID string) {
	s.mu.Lock()
	var targets []chan struct{}
	for key, set := range s.subs {
		if key.document != documentID {
			continue
		}
		for _, sub := range set {
			targets = append(targets, sub.wakes)
		}
	}
	s.mu.Unlock()

	for _, ch := range targets {
		select {
		case ch <- struct{}{}:
		default:
			// A signal the consumer has not drained yet is already pending; the
			// pending wake covers this commit too because the consumer re-reads
			// from its last observed cursor.
		}
	}
}

// SignalRevoked closes the one-shot revoked channel of every subscription open
// on (documentID, deviceID), so the connection layer ends those subscriptions
// with the permission-closed code even if a grant races in afterward. Other
// devices' and other documents' subscriptions are untouched. It is the
// permission service's revoke hook for the change event service.
func (s *Service) SignalRevoked(documentID, deviceID string) {
	s.mu.Lock()
	set := s.subs[subKey{document: documentID, device: deviceID}]
	targets := make([]*subscription, 0, len(set))
	for _, sub := range set {
		if !sub.revokedClosed {
			sub.revokedClosed = true
			targets = append(targets, sub)
		}
	}
	s.mu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// SignalDeviceDeregistered ends every live subscription belonging to
// deviceID across every document, after the device's deregistration
// transaction committed: the session backing such a connection is already
// hard-deleted, so the connection closes immediately with the same
// permission-closed code a revoke uses — stickily, nothing can reopen it.
// Other devices' subscriptions are untouched.
func (s *Service) SignalDeviceDeregistered(deviceID string) {
	s.mu.Lock()
	var targets []*subscription
	for key, set := range s.subs {
		if key.device != deviceID {
			continue
		}
		for _, sub := range set {
			if !sub.revokedClosed {
				sub.revokedClosed = true
				targets = append(targets, sub)
			}
		}
	}
	s.mu.Unlock()

	for _, sub := range targets {
		close(sub.revoked)
	}
}

// Closing reports whether the service has begun stopping. A woken subscription
// uses it to distinguish a termination signal from a commit.
func (s *Service) Closing() bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.closed
}

// interruptWaits wakes every parked long poll without closing the database, so
// an orderly shutdown drains waiting connections immediately (they answer 503)
// instead of holding shutdown hostage until their wait deadline. Committed
// state is untouched. Live subscriptions get one last wakeup as well; the
// connection layer re-checks the closed flag and finishes with a going-away
// close.
func (s *Service) InterruptWaits() {
	s.mu.Lock()
	s.closed = true
	waits := s.waits
	s.waits = map[string]map[uint64]chan struct{}{}
	// Snapshot the live subscription channels without reaping the registry:
	// unregister remains valid while handlers drain, so the WaitGroup in
	// shutdown balances. New AddSubscription calls fail fast on closed.
	var subChans []chan struct{}
	for _, set := range s.subs {
		for _, sub := range set {
			subChans = append(subChans, sub.wakes)
		}
	}
	s.mu.Unlock()
	for _, set := range waits {
		for _, ch := range set {
			close(ch)
		}
	}
	for _, ch := range subChans {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}

// waitSubscriptions blocks until every subscription handler has unregistered.
func (s *Service) WaitDrained() {
	s.subWG.Wait()
}

package events

import (
	"context"
	"database/sql"
	"time"
)

// DocumentExists reports whether documentID is a known document rather than an
// empty namespace: it has any online change row, or a compaction boundary from
// a log that was (fully or partially) trimmed.
func (s *Service) DocumentExists(documentID string) (bool, error) {
	var known bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)`,
		documentID, documentID,
	).Scan(&known); err != nil {
		return false, err
	}
	return known, nil
}

// ListChanges returns at most limit changes for documentID whose cursor is
// greater than after and still online, in cursor order, together with the
// cursor to pass as the next after value. An unknown document yields an empty
// list and cursor 0; a known document with no rows past after yields
// nextCursor == max(after, boundary), so a caller positioned inside the
// trimmed range resumes from the compaction boundary.
func (s *Service) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
	rows, err := s.db.Query(
		`SELECT id, device_id, payload, cursor FROM changes
		 WHERE document_id = ? AND cursor > ?
		 ORDER BY cursor ASC
		 LIMIT ?`,
		documentID, after, limit,
	)
	if err != nil {
		return nil, 0, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	var maxCursor int64 = after
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
		maxCursor = c.Cursor
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	// Distinguish an unknown document from a known one with nothing new:
	// unknown documents must report nextCursor 0, while a known document
	// reports the greater of after and the compaction boundary.
	if len(out) == 0 {
		known, err := s.DocumentExists(documentID)
		if err != nil {
			return nil, 0, err
		}
		if !known {
			return out, 0, nil
		}
		boundary, err := boundaryOfTx(s.db, documentID)
		if err != nil {
			return nil, 0, err
		}
		if boundary > maxCursor {
			maxCursor = boundary
		}
	}
	return out, maxCursor, nil
}

// ExportChanges returns every change of documentID whose cursor lies in the
// closed interval [from, to] and is still in the online log, in ascending
// cursor order. When to is nil no upper bound is applied. An unknown document,
// or a range without any online change — including one that lies entirely
// inside the trimmed region — yields an empty list and no error: the export is
// a read that misses like any other. The (document_id, cursor) unique index
// guarantees a cursor appears at most once.
//
// The single SELECT runs as one SQLite statement over the serialized
// connection, so a batch committed concurrently is observed either with all of
// its rows or not at all — never half of it. The read starts no transaction,
// writes nothing and notifies no waiters, so it cannot move a cursor, produce
// a change record or wake a parked poll. Each returned row is the same record
// the paged read emits at that cursor.
func (s *Service) ExportChanges(documentID string, from int64, to *int64) ([]ListedChange, error) {
	var (
		rows *sql.Rows
		err  error
	)
	if to == nil {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ?
			 ORDER BY cursor ASC`,
			documentID, from,
		)
	} else {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ? AND cursor <= ?
			 ORDER BY cursor ASC`,
			documentID, from, *to,
		)
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// WaitForChanges blocks until documentID has a change with cursor greater than
// after, a change is committed while waiting, wait elapses, ctx is canceled
// (the client disconnected) or the service stops. It then returns the current
// page of up to limit changes exactly as ListChanges would, with timedOut=true
// only when the wait deadline expired with no new rows.
//
// Registration precedes the first query: a commit landing between the read and
// the park still notifies a registered channel, so no change is missed.
//
// An unknown document is never parked on: it returns immediately with an empty
// list and nextCursor 0, timedOut=false. Data already past after is likewise
// returned immediately. wait <= 0 is an immediately expired deadline.
func (s *Service) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
	ch, remove := s.registerWait(documentID)
	defer remove()

	changes, nextCursor, err = s.ListChanges(documentID, after, limit)
	if err != nil || len(changes) > 0 {
		return changes, nextCursor, false, err
	}

	// Empty page: distinguish an unknown document (immediate empty/0, never
	// parked on) from a known document caught up to after.
	known, err := s.DocumentExists(documentID)
	if err != nil || !known {
		return changes, 0, false, err
	}

	// Known document, nothing new: a zero wait is an immediately expired
	// deadline; ListChanges already echoes nextCursor == after.
	if wait <= 0 {
		return changes, nextCursor, true, nil
	}

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-ch:
		// Woken by a committed change or by InterruptWaits.
		s.mu.Lock()
		closing := s.closed
		s.mu.Unlock()
		if closing {
			return nil, 0, false, ErrStoreClosing
		}
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-timer.C:
		// Timeout with no new rows: echo the caller's cursor without
		// advancing it. The document was known above, so ListChanges returns
		// nextCursor == after for an empty page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-ctx.Done():
		return nil, 0, false, ctx.Err()
	}
}

// registerWait parks a channel for documentID and returns it together with a
// removal function. The channel is closed on the next committed change to the
// document, or when the service stops.
func (s *Service) registerWait(documentID string) (ch chan struct{}, remove func()) {
	ch = make(chan struct{}, 1)

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		// Shutdown beat the registration: signal immediately so the caller does
		// not park on a channel nobody will close.
		close(ch)
		return ch, func() {}
	}
	s.nextWait++
	id := s.nextWait
	set := s.waits[documentID]
	if set == nil {
		set = make(map[uint64]chan struct{})
		s.waits[documentID] = set
	}
	set[id] = ch
	return ch, func() {
		s.mu.Lock()
		if set, ok := s.waits[documentID]; ok {
			delete(set, id)
			if len(set) == 0 {
				delete(s.waits, documentID)
			}
		}
		s.mu.Unlock()
	}
}

// notifyWaiters signals every long poll parked on documentID and every
// subscription open on it. It is called only after a change-bearing
// transaction has committed, so parked readers observe the new rows when they
// re-query and pushed frames describe committed changes.
func (s *Service) notifyWaiters(documentID string) {
	s.mu.Lock()
	set := s.waits[documentID]
	delete(s.waits, documentID)
	s.mu.Unlock()
	for _, ch := range set {
		close(ch)
	}
	s.signalSubscribers(documentID)
}

// Change-log compaction moves the old end of a document's change log out of
// the online tables without touching the cursor space the log shares with
// every write path.
//
// The compaction boundary is the greatest cursor that has a saved snapshot
// (zero when the document has none): everything at or below it is reproducible
// from a snapshot plus the surviving tail, so those rows leave the online log.
// A trimmed change is not forgotten, though — its id keeps a small canonical
// summary (the originating device, a digest of the payload and, for a restore,
// the snapshot it came from, plus the cursor it was first assigned) so the
// submission layer keeps answering idempotency and conflict exactly as before.
// The summary never participates in reads: pagination, long polling and
// subscriptions simply no longer see the trimmed rows, and the summary's
// fixed size means storage does not grow back to the pre-compaction shape.
//
// Compaction itself is not a change: it allocates no cursor, writes no change
// record and wakes no waiter or subscriber. The cursor space never resets —
// the next allocated cursor is one past the greater of the online maximum and
// the boundary — and the boundary, the summaries and the read results are
// durable across restarts.

package events

import (
	"bytes"
	"crypto/sha256"
	"database/sql"
	"encoding/json"
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// CompactChanges moves every change of documentID whose cursor is at or below
// the compaction boundary out of the online log, in one serialized
// transaction, and returns the boundary together with the number of changes
// removed by this call.
//
// The boundary is the greatest cursor with a saved snapshot, or zero when the
// document has no snapshot — compacting a snapshot-less or unknown document
// succeeds and removes nothing. The gate is enforced before any content is
// observed, exactly as in ReplayChanges: an unregistered device yields
// store.ErrDeviceNotFound and a revoked device yields store.ErrPermissionDenied,
// and neither touches any state.
//
// Each trimmed id keeps its canonical summary (device, payload digest, restore
// provenance and first cursor) so re-posting it stays idempotent and a
// differing re-post stays a conflict. Compaction is idempotent: a repeat finds
// the same boundary, trims nothing and reports zero removed. It commits no
// change row, allocates no cursor and notifies no waiter or subscriber.
func (s *Service) CompactChanges(documentID, deviceID string) (boundary, removed int64, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, 0, err
	}
	defer func() { _ = tx.Rollback() }()

	// Registration and permission are enforced before any change content is
	// observed, so a rejected compaction cannot reveal anything.
	if s.gate != nil {
		if err := s.gate.DeviceAuthorizedTx(tx, documentID, deviceID); err != nil {
			return 0, 0, err
		}
	}

	// The boundary is the greatest cursor with a saved snapshot, 0 when the
	// document has none (an unknown document included).
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM snapshots WHERE document_id = ?`,
		documentID,
	).Scan(&boundary); err != nil {
		return 0, 0, err
	}
	stored, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return 0, 0, err
	}
	if boundary <= stored {
		// Nothing new to trim (a repeat compaction, or a snapshot-less
		// document): report the standing boundary and remove nothing.
		return stored, 0, tx.Commit()
	}

	// Collect the rows leaving the online log before deleting them: each one
	// first moves its canonical summary into the identity table.
	type trimmed struct {
		cursor  int64
		id      string
		device  string
		payload []byte
	}
	rows, err := tx.Query(
		`SELECT cursor, id, device_id, payload FROM changes
		 WHERE document_id = ? AND cursor <= ?
		 ORDER BY cursor ASC`,
		documentID, boundary,
	)
	if err != nil {
		return 0, 0, err
	}
	var dropping []trimmed
	for rows.Next() {
		var t trimmed
		if err := rows.Scan(&t.cursor, &t.id, &t.device, &t.payload); err != nil {
			_ = rows.Close()
			return 0, 0, err
		}
		dropping = append(dropping, t)
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return 0, 0, err
	}
	_ = rows.Close()

	for _, t := range dropping {
		// A restored change also carries its provenance into the summary, so a
		// repeated restore keeps its idempotency/conflict decision.
		var restoredFrom sql.NullInt64
		err := tx.QueryRow(
			`SELECT snapshot_cursor FROM restores WHERE document_id = ? AND change_id = ?`,
			documentID, t.id,
		).Scan(&restoredFrom)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			restoredFrom = sql.NullInt64{}
		case err != nil:
			return 0, 0, err
		}
		digest, err := payloadDigest(t.payload)
		if err != nil {
			return 0, 0, err
		}
		if _, err := tx.Exec(
			`INSERT OR IGNORE INTO change_identities
				(document_id, id, device_id, digest, cursor, restored_from)
			 VALUES (?, ?, ?, ?, ?, ?)`,
			documentID, t.id, t.device, digest, t.cursor, restoredFrom,
		); err != nil {
			return 0, 0, err
		}
	}

	if _, err := tx.Exec(
		`DELETE FROM restores WHERE document_id = ? AND change_cursor <= ?`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}
	if _, err := tx.Exec(
		`DELETE FROM changes WHERE document_id = ? AND cursor <= ?`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}
	if _, err := tx.Exec(
		`INSERT INTO change_boundaries (document_id, boundary) VALUES (?, ?)
		 ON CONFLICT (document_id) DO UPDATE SET boundary = excluded.boundary`,
		documentID, boundary,
	); err != nil {
		return 0, 0, err
	}

	if err := tx.Commit(); err != nil {
		return 0, 0, err
	}
	// Compaction is not a change: no waiter is woken and no subscriber is
	// signaled, because no new change exists to observe.
	return boundary, int64(len(dropping)), nil
}

// boundaryOfTx returns the stored compaction boundary of documentID, or zero
// when the document was never compacted.
func boundaryOfTx(q store.DBTX, documentID string) (int64, error) {
	var boundary int64
	err := q.QueryRow(
		`SELECT boundary FROM change_boundaries WHERE document_id = ?`,
		documentID,
	).Scan(&boundary)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return 0, nil
	case err != nil:
		return 0, err
	default:
		return boundary, nil
	}
}

// currentCursorTx returns the document's high-water mark: the greatest online
// cursor, or the compaction boundary when every change up to it has left the
// online log. The cursor space never resets, so a fully trimmed document
// continues from its boundary rather than from zero.
func currentCursorTx(tx *sql.Tx, documentID string) (int64, error) {
	var maxOnline int64
	if err := tx.QueryRow(
		`SELECT COALESCE(MAX(cursor), 0) FROM changes WHERE document_id = ?`,
		documentID,
	).Scan(&maxOnline); err != nil {
		return 0, err
	}
	boundary, err := boundaryOfTx(tx, documentID)
	if err != nil {
		return 0, err
	}
	if boundary > maxOnline {
		maxOnline = boundary
	}
	return maxOnline, nil
}

// payloadDigest renders a payload in the canonical form JSONEqual compares —
// the decoded value re-encoded, so 1 and 1.0 or reordered object keys digest
// alike — and hashes it. The digest is the fixed-size stand-in for the payload
// in a trimmed change's retained summary.
func payloadDigest(payload json.RawMessage) ([]byte, error) {
	var v any
	if err := json.Unmarshal(payload, &v); err != nil {
		return nil, err
	}
	canonical, err := json.Marshal(v)
	if err != nil {
		return nil, err
	}
	sum := sha256.Sum256(canonical)
	return sum[:], nil
}

// resolveTrimmedIdentity answers the submission question for an id whose
// online row is absent because compaction trimmed it. It returns found=true
// and the id's first cursor when the retained summary matches the incoming
// device and payload (an idempotent re-post), an *ErrConflict when a retained
// summary exists but differs, and found=false when no summary was retained (a
// genuinely new id).
func resolveTrimmedIdentity(tx *sql.Tx, documentID string, c Change) (found bool, cursor int64, err error) {
	var device string
	var digest []byte
	err = tx.QueryRow(
		`SELECT device_id, digest, cursor FROM change_identities WHERE document_id = ? AND id = ?`,
		documentID, c.ID,
	).Scan(&device, &digest, &cursor)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, 0, nil
	case err != nil:
		return false, 0, err
	}

	incoming, err := payloadDigest(c.Payload)
	if err != nil {
		return false, 0, err
	}
	if device != c.DeviceID || !bytes.Equal(digest, incoming) {
		return false, 0, &ErrConflict{ID: c.ID}
	}
	return true, cursor, nil
}

// Package authz is the permission service: the durable, per-document and
// per-device authorization ledger together with the system's single revoke
// verdict.
//
// Every (document, device) pair starts authorized; a grant or revoke is
// recorded per pair. The lookup and the write run in one serialized
// transaction on the shared connection and commit to disk, so concurrent
// grant/revoke calls each land as a complete state and survive a restart.
//
// The other services do not read the permission table. They take their
// registration-and-authorization verdict through AuthorizedTx, evaluated
// inside their own write transaction, so a rejected request is judged before
// any document content is observed and the gate and the gated work commit as
// one judgment. Revoking never deletes changes, snapshots, sessions or CRDT
// state; it only produces the denial and, after the revoke commits, notifies
// the registered revoke sinks (the live subscription registries) so they can
// end the affected connections with the one-time, sticky 4403 close.
package authz

import (
	"database/sql"
	"errors"
	"sync"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// schema is created when the service is constructed; its shape is unchanged
// from the pre-refactor layout, so authorization rows already on disk stay
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS document_permissions (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	authorized  INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
`

// RevokeSink observes a committed revoke. The change event service and the
// CRDT service register themselves to end the affected live subscriptions; a
// sink must not block and must be safe to call after the revoke transaction
// has committed. The permission service depends on this interface alone, so
// the dependency points from the observers toward the verdict and never back.
type RevokeSink interface {
	PermissionRevoked(documentID, deviceID string)
}

// Service is the permission service.
type Service struct {
	db *sql.DB

	mu    sync.Mutex
	sinks []RevokeSink
}

// New constructs the permission service over the shared kernel handle and
// creates its table.
func New(kernel *store.Store) (*Service, error) {
	db := kernel.DB()
	if _, err := db.Exec(schema); err != nil {
		return nil, err
	}
	return &Service{db: db}, nil
}

// AddRevokeSink registers an observer notified after every committed revoke.
// It is called by the composition root while wiring the services, before the
// surface serves requests.
func (s *Service) AddRevokeSink(sink RevokeSink) {
	s.mu.Lock()
	s.sinks = append(s.sinks, sink)
	s.mu.Unlock()
}

// AuthorizedTx is the shared gate: it returns nil when deviceID is registered
// and currently authorized for documentID, store.ErrDeviceNotFound when the
// device is not registered and store.ErrPermissionDenied when its access has
// been revoked. It runs inside the caller's transaction q, so the verdict is
// taken on the same serialized connection as the work it guards, before any
// document content is read.
func (s *Service) AuthorizedTx(q store.DBTX, documentID, deviceID string) error {
	exists, err := store.DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return store.ErrDeviceNotFound
	}
	var stored int
	err = q.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
		return nil
	case err != nil:
		return err
	default:
		if stored == 0 {
			return store.ErrPermissionDenied
		}
		return nil
	}
}

// DeviceAuthorizedTx adapts the shared gate to the change event and CRDT
// services' Gate interface (which names *sql.Tx). The verdict is identical.
func (s *Service) DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error {
	return s.AuthorizedTx(tx, documentID, deviceID)
}

// SetDocumentPermission grants or revokes deviceID's access to documentID and
// reports whether the stored permission actually changed.
//
// Every device starts authorized for every document, so the first revoke is
// the first write for the pair (changed=true); repeating a state that already
// holds writes nothing and reports changed=false. An unregistered device
// yields store.ErrDeviceNotFound and nothing is written. The lookup and the
// write run in one serialized transaction, so concurrent grant/revoke calls
// each commit completely and the final state matches the last committed
// action. After a revoke commits, every registered sink is notified; a grant
// notifies nothing (a prior revoke already ended the connection stickily).
func (s *Service) SetDocumentPermission(documentID, deviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := store.DeviceExistsTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, store.ErrDeviceNotFound
	}

	current := true // devices start authorized; a row only records a deviation
	var stored int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No row: the default (authorized) holds.
	case err != nil:
		return false, err
	default:
		current = stored != 0
	}
	if current == authorized {
		return false, tx.Commit()
	}

	v := 0
	if authorized {
		v = 1
	}
	if _, err := tx.Exec(
		`INSERT INTO document_permissions (document_id, device_id, authorized) VALUES (?, ?, ?)
		 ON CONFLICT (document_id, device_id) DO UPDATE SET authorized = excluded.authorized`,
		documentID, deviceID, v,
	); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}

	// A grant cannot unblock a subscription (the first revoke already ended
	// it, stickily); only a revoke needs to end live subscriptions.
	if !authorized {
		s.mu.Lock()
		sinks := append([]RevokeSink(nil), s.sinks...)
		s.mu.Unlock()
		for _, sink := range sinks {
			sink.PermissionRevoked(documentID, deviceID)
		}
	}
	return true, nil
}

// DeleteDevicePermissionsTx removes every document-permission ledger row that
// names deviceID, inside the caller's transaction: grants and revokes the
// deregistered device held on documents vanish together with the device. It is
// the permission service's share of device deregistration, run in the same
// serialized transaction as the registration layer's cascade, so the row
// removals and the device deletion commit as one judgment. After the device
// row is gone the default verdict would be "unregistered" anyway; clearing the
// rows guarantees a device that later re-registers the same id starts with no
// inherited authorization state.
func (s *Service) DeleteDevicePermissionsTx(q store.DBTX, deviceID string) error {
	_, err := q.Exec(
		`DELETE FROM document_permissions WHERE device_id = ?`, deviceID,
	)
	return err
}

// DocumentAuthorized reports whether deviceID currently holds permission for
// documentID. Devices start authorized, so an absent row means authorized.
func (s *Service) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	var stored int
	err := s.db.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return true, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

// PermissionEntry is one row of a document's permission ledger: a currently
// registered device id together with its authorization for the document.
type PermissionEntry struct {
	DeviceID   string
	Authorized bool
}

// ListDocumentPermissions is the read-only ledger view of one document: one
// entry per currently registered device, in ascending lexicographic device-id
// order, paged by limit/offset against that same order.
//
// A device with no ledger row starts authorized, so its entry reports
// Authorized=true; a device whose latest committed action was a revoke reports
// false. Deregistered devices carry no device row and their ledger rows were
// removed by the deregistration cascade, so they never appear. An unknown
// document is indistinguishable from one on which every device keeps the
// default: every registered device lists authorized. The read runs in one
// serialized transaction, creates no row, moves no cursor and notifies no sink.
func (s *Service) ListDocumentPermissions(documentID string, limit, offset int64) ([]PermissionEntry, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	rows, err := tx.Query(
		`SELECT d.id, COALESCE(p.authorized, 1) AS authorized
		 FROM devices d
		 LEFT JOIN document_permissions p
		   ON p.document_id = ? AND p.device_id = d.id
		 ORDER BY d.id ASC
		 LIMIT ? OFFSET ?`,
		documentID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	entries := make([]PermissionEntry, 0)
	for rows.Next() {
		var entry PermissionEntry
		var stored int
		if err := rows.Scan(&entry.DeviceID, &stored); err != nil {
			return nil, err
		}
		entry.Authorized = stored != 0
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return entries, tx.Commit()
}

