108			t.Fatalf("repost status = %d body = %s", w.Code, w.Body.String())
109		}
110		if body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
111			t.Fatalf("idempotent = %v", body)
112		}
113		res := body["result"].(map[string]any)
114		if res["id"] != "x" || res["created"] != false || res["cursor"].(float64) != 1 {
115			t.Fatalf("embedded result = %v", res)
116		}
117		want := `{"id":"x","outcome":"idempotent","cursor":1,` +
118			`"result":{"id":"x","created":false,"cursor":1}}` + "\n"
119		if w.Body.String() != want {
120			t.Fatalf("body = %q\nwant %q", w.Body.String(), want)
121		}
122	
123		// No new row was written.
124		rows, next, err := s.ListChanges("doc1", 0, 100)
125		if err != nil {
126			t.Fatal(err)
127		}
128		if len(rows) != 1 || next != 1 {
