159			t.Fatalf("device conflict = %d body = %s", w.Code, w.Body.String())
160		}
161	
162		// Top-level key collision with a later payload: 409, zero writes.
163		w, _ = postSessionMerge(t, h, "sess", "doc1", `{"baseCursor":0,"change":{"id":"clash","payload":{"k":99}}}`)
164		if w.Code != http.StatusConflict {
165			t.Fatalf("key clash = %d body = %s", w.Code, w.Body.String())
166		}
