168		// A non-object payload after the base cursor blocks the merge: 409.
169		w, _ = postJSON(t, h, "/v1/documents/doc1/changes", map[string]any{
170			"deviceId": "dev",
171			"changes":  []any{map[string]any{"id": "arr", "payload": []any{1, 2}}},
172		})
173		if w.Code != http.StatusOK {
174			t.Fatal(w.Body.String())
175		}
176		w, _ = postSessionMerge(t, h, "sess", "doc1", `{"baseCursor":0,"change":{"id":"nonobj","payload":{"q":1}}}`)
177		if w.Code != http.StatusConflict {
178			t.Fatalf("non-object later = %d body = %s", w.Code, w.Body.String())
179		}
180	
181		// Every conflict left the log at its single original row.
182		rows, next, err := s.ListChanges("doc1", 0, 100)
183		if err != nil {
184			t.Fatal(err)
185		}
186		if len(rows) != 2 || next != 2 {
