574		const n = 40
575		var wg sync.WaitGroup
576		errs := make(chan error, n)
577		var applied int64
578		var mu sync.Mutex
579		for i := 0; i < n; i++ {
580			wg.Add(1)
581			go func(i int) {
582				defer wg.Done()
583				// Every goroutine merges from baseCursor 0 with a unique top-level
584				// key, so serialization leaves each merge applicable.
585				w, body := postSessionMerge(t, h, "sess", "doc", map[string]any{
586					"baseCursor": 0,
587					"change": map[string]any{
588						"id":      fmt.Sprintf("id-%02d", i),
589						"payload": map[string]any{fmt.Sprintf("k%02d", i): i},
590					},
591				})
592				if w.Code != http.StatusOK {
593					errs <- fmt.Errorf("merge %d status %d: %s", i, w.Code, w.Body.String())
594					return
595				}
596				mu.Lock()
597				if body["outcome"] == "applied" {
598					applied++
599				}
600				mu.Unlock()
601			}(i)
602		}
603		wg.Wait()
604		close(errs)
605		for err := range errs {
606			t.Error(err)
607		}
608	
609		// Exactly one request won the applied race; the whole set took effect with
610		// no cursor reused and no record lost.
611		if applied != 1 {
612			t.Fatalf("applied count = %d, want 1", applied)
613		}
614		w, body := doRequest(t, h, http.MethodGet, "/v1/documents/doc/changes?limit=1000")
615		if w.Code != http.StatusOK {
616			t.Fatal(w.Body.String())
617		}
618		rows := body["changes"].([]any)
619		if len(rows) != n || body["nextCursor"].(float64) != n {
620			t.Fatalf("stored %d changes, nextCursor = %v, want %d", len(rows), body["nextCursor"], n)
621		}
622		seen := make(map[float64]bool, n)
623		for _, row := range rows {
624			cursor := row.(map[string]any)["cursor"].(float64)
625			if seen[cursor] {
626				t.Fatalf("cursor %v allocated twice", cursor)
627			}
628			seen[cursor] = true
629		}
630	}
631	
632	func TestSessionMergeHTTPPersistenceAcrossRestart(t *testing.T) {
633		path := filepath.Join(t.TempDir(), "session-merge.db")
634	
635		s, err := app.Open(path)
636		if err != nil {
637			t.Fatal(err)
638		}
639		h := NewHandler(s)
640		createSessionViaHTTP(t, h, "dev", "sess")
641		w, _ := postSessionMerge(t, h, "sess", "doc1", `{"baseCursor":0,"change":{"id":"c1","payload":{"a":1}}}`)
642		if w.Code != http.StatusOK {
643			t.Fatal(w.Body.String())
644		}
645		if err := s.Close(); err != nil {
646			t.Fatal(err)
647		}
648	
649		s2, err := app.Open(path)
650		if err != nil {
651			t.Fatal(err)
652		}
653		t.Cleanup(func() { _ = s2.Close() })
654		h2 := NewHandler(s2)
655	
656		// Idempotency survives the restart.
657		w, body := postSessionMerge(t, h2, "sess", "doc1", `{"baseCursor":1,"change":{"id":"c1","payload":{"a":1.0}}}`)
658		if w.Code != http.StatusOK {
659			t.Fatal(w.Body.String())
660		}
661		if body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
662			t.Fatalf("idempotent after restart = %v", body)
663		}
664	
665		// The conflict decision survives too.
666		w, body = postSessionMerge(t, h2, "sess", "doc1", `{"baseCursor":1,"change":{"id":"c1","payload":{"a":2}}}`)
667		if w.Code != http.StatusConflict {
668			t.Fatalf("conflict after restart = %d %s", w.Code, w.Body.String())
669		}
670	
671		// A merge at the current cursor appends, continuing the durable cursor.
672		w, body = postSessionMerge(t, h2, "sess", "doc1", `{"baseCursor":1,"change":{"id":"c2","payload":{"b":2}}}`)
673		if w.Code != http.StatusOK || body["outcome"] != "applied" || body["cursor"].(float64) != 2 {
674			t.Fatalf("post-restart merge = %d %v", w.Code, body)
675		}
676	
677		// A stale base (1) behind the current cursor merges when its keys are
678		// disjoint from every later payload, continuing the durable cursor.
679		w, body = postSessionMerge(t, h2, "sess", "doc1", `{"baseCursor":1,"change":{"id":"c3","payload":{"c":3}}}`)
680		if w.Code != http.StatusOK || body["outcome"] != "merged" || body["cursor"].(float64) != 3 {
681			t.Fatalf("post-restart stale merge = %d %v", w.Code, body)
682		}
683		w, body = postSessionMerge(t, h2, "sess", "doc1", `{"baseCursor":1,"change":{"id":"c4","payload":{"d":4}}}`)
684		if w.Code != http.StatusOK || body["outcome"] != "merged" || body["cursor"].(float64) != 4 {
685			t.Fatalf("post-restart stale merge = %d %v", w.Code, body)
686		}
687	}
