21	var (
22		binaryPath string
23		buildOnce  sync.Once
24		buildErr   error
25	)
26	
27	// buildBinary compiles the real syncd entrypoint once for the process tests.
28	func buildBinary(t *testing.T) string {
29		t.Helper()
30		buildOnce.Do(func() {
31			dir, err := os.MkdirTemp("", "syncd-bin")
32			if err != nil {
33				buildErr = err
34				return
35			}
36			binaryPath = filepath.Join(dir, "syncd")
37			buildErr = exec.Command("go", "build", "-o", binaryPath,
38				"github.com/alicegogogogogo/local-first-sync-service/cmd/syncd").Run()
39		})
40		if buildErr != nil {
41			t.Fatalf("build syncd: %v", buildErr)
42		}
43		return binaryPath
44	}
45	
46	type process struct {
47		cmd     *exec.Cmd
48		out     *safeBuffer
49		addr    string
50		dataDir string
51		exited  chan error // closed once Wait returns, carrying the exit error
52	}
53	
54	type safeBuffer struct {
55		mu  sync.Mutex
56		buf bytes.Buffer
57	}
58	
59	func (s *safeBuffer) Write(p []byte) (int, error) {
60		s.mu.Lock()
61		defer s.mu.Unlock()
62		return s.buf.Write(p)
63	}
64	
65	func (s *safeBuffer) String() string {
66		s.mu.Lock()
67		defer s.mu.Unlock()
68		return s.buf.String()
69	}
70	
71	var listeningLine = regexp.MustCompile(`sync service listening on (\S+) \(data: (.*)\)`)
72	
73	// startProcess launches syncd with the given environment and waits for the
74	// startup line, returning the actual endpoint parsed from it.
75	func startProcess(t *testing.T, env ...string) *process {
76		t.Helper()
77		p := &process{
78			cmd:    exec.Command(buildBinary(t)),
79			out:    &safeBuffer{},
80			exited: make(chan error, 1),
81		}
82		p.cmd.Env = append(os.Environ(), env...)
83		p.cmd.Stdout = p.out
84		p.cmd.Stderr = p.out
85		if err := p.cmd.Start(); err != nil {
86			t.Fatalf("start syncd: %v", err)
87		}
88		go func() { p.exited <- p.cmd.Wait() }()
89	
90		deadline := time.Now().Add(15 * time.Second)
91		ticker := time.NewTicker(5 * time.Millisecond)
92		defer ticker.Stop()
93		for time.Now().Before(deadline) {
94			if m := listeningLine.FindStringSubmatch(p.out.String()); m != nil {
95				p.addr = m[1]
96				p.dataDir = m[2]
97				return p
98			}
99			select {
100			case err := <-p.exited:
101				t.Fatalf("syncd exited before reporting its endpoint (err=%v); output:\n%s", err, p.out.String())
102			default:
103			}
104			<-ticker.C
105		}
106		_ = p.cmd.Process.Kill()
107		<-p.exited
108		t.Fatalf("syncd never reported its endpoint; output:\n%s", p.out.String())
109		return nil
110	}
111	
112	func (p *process) terminate(t *testing.T) int {
113		t.Helper()
114		if err := p.cmd.Process.Signal(syscall.SIGTERM); err != nil {
115			t.Fatalf("send SIGTERM: %v", err)
116		}
117		select {
118		case err := <-p.exited:
119			if ee, ok := err.(*exec.ExitError); ok {
120				return ee.ExitCode()
121			}
122			if err != nil {
123				t.Fatalf("wait for syncd: %v", err)
124			}
125			return 0
126		case <-time.After(10 * time.Second):
127			_ = p.cmd.Process.Kill()
128			t.Fatalf("process did not exit within 10s; output:\n%s", p.out.String())
129		}
130		return -1
131	}
132	
133	func (p *process) getHealth(t *testing.T) (int, map[string]any) {
134		t.Helper()
135		return processJSON(t, http.MethodGet, "http://"+p.addr+"/healthz", nil)
136	}
137	
138	func processJSON(t *testing.T, method, url string, body any) (int, map[string]any) {
139		t.Helper()
140		var rdr io.Reader
141		if body != nil {
142			raw, _ := json.Marshal(body)
143			rdr = strings.NewReader(string(raw))
144		}
145		req, err := http.NewRequest(method, url, rdr)
146		if err != nil {
147			t.Fatal(err)
148		}
149		if body != nil {
150			req.Header.Set("Content-Type", "application/json")
151		}
152		resp, err := http.DefaultClient.Do(req)
153		if err != nil {
154			t.Fatalf("%s %s: %v", method, url, err)
155		}
156		defer resp.Body.Close()
157		raw, _ := io.ReadAll(resp.Body)
158		var decoded map[string]any
159		_ = json.Unmarshal(raw, &decoded)
160		return resp.StatusCode, decoded
161	}
162	
163	// The real binary with :0 reports the allocated endpoint and data path in its
164	// startup log, and that endpoint serves /healthz.
165	func TestProcessEphemeralAddrFromLog(t *testing.T) {
166		dataPath := filepath.Join(t.TempDir(), "sync.db")
167		p := startProcess(t, "SYNC_ADDR=127.0.0.1:0", "SYNC_DATA="+dataPath)
168		defer p.cmd.Process.Kill()
169	
170		if p.dataDir != dataPath {
171			t.Fatalf("logged data path = %q, want %q", p.dataDir, dataPath)
172		}
173		host, portStr, err := net.SplitHostPort(p.addr)
174		if err != nil {
175			t.Fatalf("logged addr %q: %v", p.addr, err)
176		}
177		port, err := strconv.Atoi(portStr)
178		if err != nil || port == 0 {
179			t.Fatalf("logged port = %q, want a non-zero allocated port", portStr)
180		}
181		if host != "127.0.0.1" {
182			t.Fatalf("logged host = %q, want 127.0.0.1", host)
183		}
184	
185		status, body := p.getHealth(t)
186		if status != http.StatusOK || body["status"] != "ok" {
187			t.Fatalf("healthz = %d %v, want 200 status=ok", status, body)
188		}
189	
190		if code := p.terminate(t); code != 0 {
191			t.Fatalf("exit code after SIGTERM = %d, want 0; output:\n%s", code, p.out.String())
192		}
193	}
194	
195	// A malformed SYNC_ADDR exits non-zero with a clear error and no listening line.
196	func TestProcessInvalidAddrExitsNonZero(t *testing.T) {
197		for _, bad := range []string{"not-an-address", "127.0.0.1:99999"} {
198			cmd := exec.Command(buildBinary(t))
199			cmd.Env = append(os.Environ(),
200				"SYNC_ADDR="+bad,
201				"SYNC_DATA="+filepath.Join(t.TempDir(), "sync.db"))
202			var out bytes.Buffer
203			cmd.Stdout = &out
204			cmd.Stderr = &out
205			err := cmd.Run()
206			if err == nil {
207				t.Fatalf("SYNC_ADDR=%q exited zero, want non-zero", bad)
208			}
209			if ee, ok := err.(*exec.ExitError); ok && ee.ExitCode() == 0 {
210				t.Fatalf("SYNC_ADDR=%q exited zero, want non-zero", bad)
211			}
212			if !strings.Contains(out.String(), "invalid SYNC_ADDR") {
213				t.Fatalf("SYNC_ADDR=%q output = %q, want invalid SYNC_ADDR", bad, out.String())
214			}
215			if listeningLine.MatchString(out.String()) {
216				t.Fatalf("SYNC_ADDR=%q printed a listening line despite failure", bad)
217			}
218		}
219	}
220	
221	// A fixed-port clash makes the second process exit non-zero; the first keeps
222	// serving. Restarting after the first stops binds the same address again.
223	func TestProcessPortConflictAndRestart(t *testing.T) {
224		ln, err := net.Listen("tcp", "127.0.0.1:0")
225		if err != nil {
226			t.Fatal(err)
227		}
228		addr := ln.Addr().String()
229		if err := ln.Close(); err != nil {
230			t.Fatal(err)
231		}
232		dataPath := filepath.Join(t.TempDir(), "sync.db")
233	
234		first := startProcess(t, "SYNC_ADDR="+addr, "SYNC_DATA="+dataPath)
235		if first.addr != addr {
236			t.Fatalf("first instance addr = %q, want %q", first.addr, addr)
237		}
238	
239		conflict := exec.Command(buildBinary(t))
240		var out bytes.Buffer
241		conflict.Env = append(os.Environ(),
242			"SYNC_ADDR="+addr,
243			"SYNC_DATA="+filepath.Join(t.TempDir(), "sync.db"))
244		conflict.Stdout = &out
245		conflict.Stderr = &out
246		if err := conflict.Run(); err == nil {
247			t.Fatal("conflicting process exited zero, want non-zero")
248		} else if ee, ok := err.(*exec.ExitError); ok && ee.ExitCode() == 0 {
249			t.Fatal("conflicting process exited zero, want non-zero")
250		}
251		if !strings.Contains(out.String(), "listen on "+addr) {
252			t.Fatalf("conflict output = %q, want listen error for %s", out.String(), addr)
253		}
254	
255		status, body := first.getHealth(t)
256		if status != http.StatusOK || body["status"] != "ok" {
257			t.Fatalf("first instance health during clash: %d %v", status, body)
258		}
259		if code := first.terminate(t); code != 0 {
260			t.Fatalf("first instance exit code = %d", code)
261		}
262	
263		// Restart with the same fixed address constraint succeeds now the port is free.
264		restart := startProcess(t, "SYNC_ADDR="+addr, "SYNC_DATA="+dataPath)
265		if code := restart.terminate(t); code != 0 {
266			t.Fatalf("restart exit code = %d; output:\n%s", code, restart.out.String())
267		}
268	}
269	
270	// An unwritable SYNC_DATA exits non-zero with a clear error.
271	func TestProcessBadDataPathExitsNonZero(t *testing.T) {
272		blocker := filepath.Join(t.TempDir(), "blocker")
273		if err := os.WriteFile(blocker, []byte("x"), 0o644); err != nil {
274			t.Fatal(err)
275		}
276		cmd := exec.Command(buildBinary(t))
277		var out bytes.Buffer
278		cmd.Env = append(os.Environ(),
279			"SYNC_ADDR=127.0.0.1:0",
280			"SYNC_DATA="+filepath.Join(blocker, "dir", "sync.db"))
281		cmd.Stdout = &out
282		cmd.Stderr = &out
283		if err := cmd.Run(); err == nil {
284			t.Fatal("bad SYNC_DATA exited zero, want non-zero")
285		} else if ee, ok := err.(*exec.ExitError); ok && ee.ExitCode() == 0 {
286			t.Fatal("bad SYNC_DATA exited zero, want non-zero")
287		}
288		combined := out.String()
289		if !strings.Contains(combined, "create data directory") && !strings.Contains(combined, "open store") {
290			t.Fatalf("output = %q, want data directory or store open error", combined)
291		}
292		if listeningLine.MatchString(combined) {
293			t.Fatal("bad SYNC_DATA printed a listening line despite failure")
294		}
295	}
296	
297	// A committed device survives SIGTERM and is visible after a restart against
298	// the same data path; the stop is graceful and exits zero.
299	func TestProcessSignalPersistsCommittedState(t *testing.T) {
300		ln, err := net.Listen("tcp", "127.0.0.1:0")
301		if err != nil {
302			t.Fatal(err)
303		}
304		addr := ln.Addr().String()
305		_ = ln.Close()
306		dataPath := filepath.Join(t.TempDir(), "sync.db")
307	
308		first := startProcess(t, "SYNC_ADDR="+addr, "SYNC_DATA="+dataPath)
309		status, body := processJSON(t, http.MethodPost, "http://"+first.addr+"/v1/devices",
310			map[string]string{"deviceId": "persisted"})
311		if status != http.StatusOK || body["created"] != true {
312			t.Fatalf("register: %d %v", status, body)
313		}
314		if code := first.terminate(t); code != 0 {
315			t.Fatalf("SIGTERM exit code = %d, want 0", code)
316		}
317	
318		second := startProcess(t, "SYNC_ADDR="+addr, "SYNC_DATA="+dataPath)
319		defer second.cmd.Process.Kill()
320		status, body = processJSON(t, http.MethodPost, "http://"+second.addr+"/v1/devices",
321			map[string]string{"deviceId": "persisted"})
322		if status != http.StatusOK || body["created"] != false {
323			t.Fatalf("re-register after restart: %d %v, want created=false", status, body)
324		}
325	}
326	
327	// Two real processes started at once on :0 with distinct data paths each get
328	// their own endpoint from their own log line, and a device registered in one
329	// is absent from the other.
330	func TestProcessTwoEphemeralInstances(t *testing.T) {
331		a := startProcess(t, "SYNC_ADDR=127.0.0.1:0", "SYNC_DATA="+filepath.Join(t.TempDir(), "a.db"))
332		defer a.cmd.Process.Kill()
333		b := startProcess(t, "SYNC_ADDR=127.0.0.1:0", "SYNC_DATA="+filepath.Join(t.TempDir(), "b.db"))
334		defer b.cmd.Process.Kill()
335		if a.addr == b.addr {
336			t.Fatalf("both processes report endpoint %s", a.addr)
337		}
338	
339		if status, body := processJSON(t, http.MethodPost, "http://"+a.addr+"/v1/devices",
340			map[string]string{"deviceId": "shared-name"}); status != http.StatusOK || body["created"] != true {
341			t.Fatalf("register in A: %d %v", status, body)
342		}
343		if status, body := processJSON(t, http.MethodPost, "http://"+b.addr+"/v1/devices",
344			map[string]string{"deviceId": "shared-name"}); status != http.StatusOK || body["created"] != true {
345			t.Fatalf("register in B: %d %v, want independent created=true", status, body)
346		}
347		if status, body := processJSON(t, http.MethodPost, "http://"+a.addr+"/v1/devices",
348			map[string]string{"deviceId": "shared-name"}); status != http.StatusOK || body["created"] != false {
349			t.Fatalf("repeat register in A: %d %v, want created=false", status, body)
350		}
351		if code := a.terminate(t); code != 0 {
352			t.Fatalf("A exit = %d", code)
353		}
354		if code := b.terminate(t); code != 0 {
355			t.Fatalf("B exit = %d", code)
356		}
357	}
