		if len(res.changes) != 2 || res.next != 2 || res.timedOut {
			t.Fatalf("result = %+v rows=%v", res, res.changes)
		}
	case <-time.After(time.Second):
		t.Fatal("poll blocked despite existing rows")
	}
}

